124	/** Pull a custom tool-use out of an event, tolerating a few shapes across SDK versions. */
125	export function extractToolUse(event) {
126	  // Direct event form.
127	  if (event?.type === "assistant.custom_tool_use" || event?.type === "custom_tool_use") {
128	    return { id: event.custom_tool_use_id ?? event.id, name: event.name, input: event.input };
129	  }
130	  // Content-block form on an assistant message.
131	  const blocks = event?.message?.content ?? event?.content;
132	  if (Array.isArray(blocks)) {
133	    const tu = blocks.find((b) => b?.type === "custom_tool_use" || b?.type === "tool_use");
134	    if (tu) return { id: tu.id ?? tu.custom_tool_use_id, name: tu.name, input: tu.input };
135	  }
136	  return null;
