141	 * against docs/rubric.json via the control plane (no preview access required).
142	 */
143	export async function isDone({ studyId, controlPlane, outcomesEnabled, session, sessionId }) {
144	  if (outcomesEnabled && session?.getOutcome) {
145	    try {
146	      const outcome = await session.getOutcome(sessionId);
147	      if (outcome?.status === "satisfied" || outcome?.verdict === "done") return true;
148	    } catch {
149	      /* fall through to rubric grade */
150	    }
