  }, required: ['lens', 'issues', 'build_ok', 'summary' ],
}
const base = `You are adversarially reviewing the Stage 3 cockpit-live changes just made in the worktree at ${repo} (cwd there). The implementer reported:\n"""${impl}"""\n\nDo NOT trust the report — read the actual changed files (use \`git diff\` and read the new files) and independently verify. ` + SSE_CONTRACT
