])

const issues = reviews.filter(Boolean).flatMap((r) => (r.issues ?? []).map((i) => ({ ...i, lens: r.lens })))
const buildOk = reviews.filter(Boolean).every((r) => r.build_ok)
return { implementerSummary: impl, buildOk, reviews: reviews.filter(Boolean).map((r) => ({ lens: r.lens, build_ok: r.build_ok, summary: r.summary, issueCount: (r.issues ?? []).length })), issues }

