1	/**
2	 * Labmate Cloudflare Worker — the control plane API for the evidence ledger.
3	 *
4	 * One Worker, backed by D1 (the ledger), R2 (artifacts), and a Durable Object
5	 * (live study session). It is the single contract both clients hit: the MCP server
6	 * (Claude's semantic tools) and the cockpit (the human's mission control). Every
7	 * route here matches apps/api-spec/openapi.yaml.
8	 *
9	 * Routes (all POST require the internal bearer token; the two GET reads are public):
10	 *   POST /api/studies               create_study           -> 201 { id, status }
11	 *   GET  /api/studies               list studies (public)  -> 200 { studies }
12	 *   GET  /api/studies/:id           study detail (public)  -> 200 StudyDetail | 404
13	 *   POST /api/profile               profile_dataset        -> 200 DatasetVersion | 404
14	 *   POST /api/experiments/propose   propose_experiments    -> 200 { hypotheses }
15	 *   POST /api/approvals/request     request_approval       -> 200 { approval_id, status }
16	 *   POST /api/experiments/launch    launch_experiment      -> 201 Run | 402 | 422
17	 *   POST /api/runs/query            query_runs             -> 200 { runs }
18	 *   POST /api/feedback              record_human_feedback  -> 201 Feedback
19	 *   POST /api/reports               write_report           -> 201 Report
20	 *   POST /api/grade                 grade_study_against_rubric -> 200 GradeResult | 404
21	 *
22	 * Bindings (wrangler.toml): env.DB (D1), env.ARTIFACTS (R2), env.STUDY (Durable Object),
23	 * env.LABMATE_INTERNAL_TOKEN (secret), env.MODAL_RUNNER_URL (the fixed runner).
24	 */
25	
26	import rubric from "../../../docs/rubric.json";
27	import schemaSQL from "../schema.sql";
28	import { profileFor, hypothesisLibrary } from "./profiles.js";
29	import { evaluateRubric } from "./grade.js";
30	
31	// ---------------------------------------------------------------------------
32	// HTTP helpers
33	// ---------------------------------------------------------------------------
34	
35	const CORS = {
36	  "access-control-allow-origin": "*",
37	  "access-control-allow-methods": "GET,POST,OPTIONS",
38	  "access-control-allow-headers": "authorization,content-type",
39	  "access-control-max-age": "86400",
40	};
41	
42	function json(data, status = 200, extra = {}) {
43	  return new Response(JSON.stringify(data), {
44	    status,
45	    headers: { "content-type": "application/json", ...CORS, ...extra },
46	  });
47	}
48	
49	const errorBody = (error, detail) => (detail ? { error, detail } : { error });
50	const fail = (status, error, detail) => json(errorBody(error, detail), status);
51	const unauthorized = () => fail(401, "unauthorized", "Missing or invalid internal token.");
52	const notFound = (detail) => fail(404, "not_found", detail);
53	
54	/** Log a server error; only reveal the raw message in dev (avoid leaking SQL/internal detail). */
55	function serverError(env, code, e) {
56	  console.error(`[labmate] ${code}:`, e && e.stack ? e.stack : e);
57	  const detail = env && env.LABMATE_ENV === "dev" ? String(e && e.message ? e.message : e) : "internal error";
58	  return fail(500, code, detail);
59	}
60	
61	/** Constant-time string compare (no early-exit on the first differing byte). */
62	function timingSafeEqual(a, b) {
63	  if (typeof a !== "string" || typeof b !== "string") return false;
64	  const enc = new TextEncoder();
65	  const ab = enc.encode(a);
66	  const bb = enc.encode(b);
67	  if (ab.length !== bb.length) return false;
68	  let diff = 0;
69	  for (let i = 0; i < ab.length; i++) diff |= ab[i] ^ bb[i];
70	  return diff === 0;
71	}
72	
73	/**
74	 * Require the shared internal token on writes. NOTE: the human checkpoint (approval)
75	 * is enforced out-of-band — the cockpit is where a human approves, which records a
76	 * feedback(type=approval); the MCP server and cockpit share LABMATE_INTERNAL_TOKEN by
77	 * design (docs/ENV.md). This token authenticates the caller, not the human approval.
78	 */
79	function checkAuth(request, env) {
80	  const auth = request.headers.get("authorization") || "";
81	  const token = auth.replace(/^Bearer\s+/i, "");
82	  return !!(token && env.LABMATE_INTERNAL_TOKEN && timingSafeEqual(token, env.LABMATE_INTERNAL_TOKEN));
83	}
84	
85	// ---------------------------------------------------------------------------
86	// small utilities
87	// ---------------------------------------------------------------------------
88	
89	const nowIso = () => new Date().toISOString();
90	
91	/** Time-prefixed, collision-resistant id: prefix_<base36 time><random>. */
92	function newId(prefix) {
93	  const t = Date.now().toString(36).padStart(9, "0");
94	  const r = crypto.randomUUID().replace(/-/g, "").slice(0, 14);
95	  return `${prefix}_${t}${r}`;
96	}
97	
98	const parse = (s, fallback = null) => {
99	  if (s === null || s === undefined) return fallback;
100	  try {
101	    return JSON.parse(s);
102	  } catch {
103	    return fallback;
104	  }
105	};
106	
107	/** Drop keys whose value is null/undefined (keeps false, 0, "", []). */
108	function compact(obj) {
109	  const out = {};
110	  for (const [k, v] of Object.entries(obj)) {
111	    if (v !== null && v !== undefined) out[k] = v;
112	  }
113	  return out;
114	}
115	
116	/** Keep only numeric metric values (the spec types metrics as map<string,number>). */
117	function numbersOnly(obj) {
118	  const out = {};
119	  for (const [k, v] of Object.entries(obj || {})) {
120	    if (typeof v === "number" && Number.isFinite(v)) out[k] = v;
121	  }
122	  return out;
123	}
124	
125	async function sha256hex(str) {
126	  const buf = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(str));
127	  return [...new Uint8Array(buf)].map((b) => b.toString(16).padStart(2, "0")).join("");
128	}
129	
130	// ---------------------------------------------------------------------------
131	// schema bootstrap (self-apply schema.sql once per isolate)
132	// ---------------------------------------------------------------------------
133	
134	let _schemaReady = null;
135	
136	function splitSql(sql) {
137	  return sql
138	    .split("\n")
139	    .map((line) => {
140	      const i = line.indexOf("--");
141	      return i >= 0 ? line.slice(0, i) : line;
142	    })
143	    .join("\n")
144	    .split(";")
145	    .map((s) => s.trim())
146	    .filter((s) => s.length > 0 && !/^PRAGMA/i.test(s));
147	}
148	
149	function ensureSchema(env) {
150	  if (!_schemaReady) {
151	    const statements = splitSql(schemaSQL).map((s) => env.DB.prepare(s));
152	    _schemaReady = env.DB.batch(statements).catch((e) => {
153	      _schemaReady = null; // allow a retry on the next request
154	      throw e;
155	    });
156	  }
157	  return _schemaReady;
158	}
159	
160	// ---------------------------------------------------------------------------
161	// row -> entity mappers (shape exactly to the OpenAPI component schemas)
162	// ---------------------------------------------------------------------------
163	
164	function mapStudy(row) {
