46	/** Stable, tabular-friendly metric formatting. Rates → 3dp, larger values → fewer. */
47	export function formatMetricValue(value: number): string {
48	  if (!Number.isFinite(value)) return '—'
49	  if (Number.isInteger(value)) return String(value)
50	  const abs = Math.abs(value)
51	  if (abs < 1) return value.toFixed(3)
52	  if (abs < 100) return value.toFixed(2)
53	  return value.toLocaleString(undefined, { maximumFractionDigits: 1 })
