58	/** The primary metric for a run: the study's metric if present, else the first. */
59	export function pickPrimaryMetric(run: Run, metricKey?: string): NamedMetric | undefined {
60	  const metrics = run.metrics
61	  if (!metrics) return undefined
62	  if (metricKey && metricKey in metrics) return { key: metricKey, value: metrics[metricKey] }
63	  const entries = Object.entries(metrics)
