143	 * notes augment/override them (a `change_metric` note steers the live study), and
144	 * for a timestamp-less mock with no constraints we still derive from feedback.
145	 */
146	export function deriveGuardrails(detail: StudyDetail): DerivedGuardrails {
147	  const guardrails = new Set<string>()
148	  let primaryMetric: string | undefined
149	
150	  // 1. Authoritative: constraints echoed on the Study.
151	  const c = detail.study?.constraints
152	  if (c) {
153	    if (typeof c.primary_metric === 'string') primaryMetric = c.primary_metric
154	    for (const g of c.guardrails ?? []) {
155	      if (g?.expr) guardrails.add(g.expr)
156	    }
157	  }
158	
159	  // 2. Augment / override with parsed feedback constraints (last note wins).
160	  for (const fb of detail.feedback ?? []) {
161	    const parsed = fb.parsed_constraints as Record<string, unknown> | undefined
162	    if (!parsed) continue
163	    if (typeof parsed.primary_metric === 'string') primaryMetric = parsed.primary_metric
164	    const g = parsed.guardrail ?? parsed.guardrails
165	    if (typeof g === 'string') guardrails.add(g)
166	    else if (Array.isArray(g)) g.forEach((x) => typeof x === 'string' && guardrails.add(x))
167	  }
168	  return { primaryMetric, guardrails: [...guardrails] }
169	}
