171	/** Banned columns = flagged leakage candidates ∪ explicit ban_feature feedback. */
172	export function deriveBannedColumns(detail: StudyDetail): Set<string> {
173	  const banned = new Set<string>()
174	  for (const col of detail.dataset_version?.columns ?? []) {
175	    if (col.is_candidate_leakage) banned.add(col.name)
176	  }
177	  for (const name of detail.study?.constraints?.banned_columns ?? []) banned.add(name)
178	  for (const fb of detail.feedback ?? []) {
179	    if (fb.type === 'ban_feature' && fb.target_id) banned.add(fb.target_id)
180	  }
