194	  else if (/precision\s+(matters|>|over|more|first|priorit)/.test(t)) out.primary_metric = 'precision'
195	  else {
196	    const m = ['recall', 'precision', 'pr_auc', 'roc_auc', 'auc', 'f1', 'rmse', 'mae', 'accuracy'].find((k) =>
197	      t.includes(k),
198	    )
199	    if (m) out.primary_metric = m
200	  }
