  const fm = md.match(/^---\s*[\r\n]([\s\S]*?)[\r\n]---/);
  const block = fm ? fm[1] : md;
  const m = block.match(/^\s*name\s*:\s*(.+?)\s*$/m);
  return m ? m[1].trim() : null;
}

/**
 * Best-effort match of an already-uploaded skill to one of ours, by the
 * frontmatter name (preferred) or display_title, case-insensitively. The exact
 * list-response field is not fully pinned (see header), so we probe several.
 */
function matchExisting(existing, { name, title }) {
  const wants = [name, title].filter(Boolean).map((s) => s.toLowerCase());
  const candidates = [
    existing?.name,
    existing?.display_title,
    existing?.title,
    existing?.latest_version?.name,
    existing?.metadata?.name,
  ]
    .filter(Boolean)
    .map((s) => String(s).toLowerCase());
  return candidates.some((c) => wants.includes(c));
}

async function listAllSkills(client) {
  const out = [];
  try {
    // skills.list auto-paginates on iteration (cursor page).
    for await (const s of client.beta.skills.list({ betas: [SKILLS_BETA] })) {
      out.push(s);
    }
  } catch (err) {
    // Listing is only used for idempotency; if it fails (e.g. endpoint shape
    // drift) we proceed to create and warn rather than abort.
    console.warn(
      `  (could not list existing skills — will create fresh: ${err?.message ?? err})`,
    );
  }
  return out;

