30	  const map = {};
31	  for (const raw of readFileSync(envPath, "utf8").split("\n")) {
32	    const line = raw.trim();
33	    if (!line || line.startsWith("#")) continue;
34	    const eq = line.indexOf("=");
35	    const colon = line.indexOf(":");
36	    const i = eq === -1 ? colon : colon === -1 ? eq : Math.min(eq, colon);
37	    if (i <= 0) continue;
