    const wait = evt.auto_approve_in_ms ? ` (auto-approving in ${Math.round(evt.auto_approve_in_ms / 1000)}s)` : "";
    console.info(`  ${t} ⏳ approval requested${wait}: ${evt.input?.reason ?? ""}`);
